package config

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func TestSanitizeConfig(t *testing.T) {
	testCases := []struct {
		description    string
		inputConfig    *Config
		expectedConfig *Config
	}{
		{
			description: "no runtime classes",
			inputConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
			},
			expectedConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
			},
		},
		{
			description: "multiple valid runtime class entries",
			inputConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
				RuntimeClasses: []RuntimeClass{
					{
						Name: "nvidia-rc-1",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-1:tag",
						},
					},
					{
						Name: "nvidia-rc-2",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-2:tag",
						},
					},
				},
			},
			expectedConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
				RuntimeClasses: []RuntimeClass{
					{
						Name: "nvidia-rc-1",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-1:tag",
						},
					},
					{
						Name: "nvidia-rc-2",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-2:tag",
						},
					},
				},
			},
		},
		{
			description: "invalid runtime class name sanitized",
			inputConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
				RuntimeClasses: []RuntimeClass{
					{
						Name: "",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-1:tag",
						},
					},
					{
						Name: "nvidia-rc-2",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-2:tag",
						},
					},
				},
			},
			expectedConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
				RuntimeClasses: []RuntimeClass{
					{
						Name: "nvidia-rc-2",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-2:tag",
						},
					},
				},
			},
		},
		{
			description: "invalid artifact url sanitized",
			inputConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
				RuntimeClasses: []RuntimeClass{
					{
						Name: "nvidia-rc-1",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-1:tag",
						},
					},
					{
						Name: "nvidia-rc-2",
						Artifacts: Artifacts{
							URL: "",
						},
					},
				},
			},
			expectedConfig: &Config{
				ArtifactsDir: DefaultKataArtifactsDir,
				RuntimeClasses: []RuntimeClass{
					{
						Name: "nvidia-rc-1",
						Artifacts: Artifacts{
							URL: "/path/to/artifact-1:tag",
						},
					},
				},
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			SanitizeConfig(tc.inputConfig)
			require.Equal(t, tc.inputConfig, tc.expectedConfig)
		})
	}
}

