				nvpcilib: &nvpciInterfaceMock{
					GetGPUsFunc: func() ([]*nvpci.NvidiaPCIDevice, error) {
						devices := []*nvpci.NvidiaPCIDevice{
							{
								Address:    "000:3B:00.0",
